/* THE BRAVE WAY — missions & scenarios. Every text is [Bahasa Indonesia, English]. */
window.AB = window.AB || {};
const MF = [["Mitos","Myth"],["Fakta","Fact"]];
AB.MF = MF;

AB.missions = [
/* ───────────────────────── MISSION 1 ───────────────────────── */
{ id:1, icon:"🛡️", badge:"shield", cat:"safety", mod:1, bg:"sekolah",
  title:["Tawaran Tak Terduga","The Unexpected Offer"],
  place:["Lingkungan sekolah","School surroundings"],
  mech:[["Komik interaktif","Interactive comic"],["Pilih jalanmu","Choose your path"],["Tantangan keselamatan","Safety challenge"]],
  intro:["Sepulang sekolah, ada saja tawaran yang datang tiba-tiba. Bisakah kamu mengenali tanda bahaya dan memilih langkah yang aman?","Offers can show up suddenly around school. Can you spot the warning signs and choose a safe step?"],
  reward:["Perisai Keselamatan","Safety Shield"],
  rewardDesc:["Kamu bisa mengenali tawaran yang tidak aman dan memilih tindakan yang melindungi dirimu.","You can recognise unsafe offers and choose actions that protect you."],
  scenes:[
  { title:["Tawaran \"Pintar Semalaman\"","The \"Study All Night\" Offer"], bg:"sekolah", cast:["bayu"], type:"choice", cat:"safety",
    lines:[["nar",["Jam istirahat. Kamu berjalan di dekat gerbang sekolah.","Break time. You are walking near the school gate."]],
           ["bayu",["Eh, mau coba ini? Sepupuku yang kasih. Katanya bikin kuat belajar semalaman.","Hey, want to try this? My cousin gave it to me. He says it keeps you awake to study all night."]],
           ["bayu",["Tenang, cuma sekali kok. Nggak ada yang tahu.","Relax, just once. Nobody will know."]]],
    q:["Apa yang kamu lakukan?","What do you do?"],
    opts:[
     {t:["Tidak, terima kasih. Aku tidak tahu itu apa, jadi aku tidak mau.","No, thank you. I don't know what it is, so I won't take it."],pts:20,
      fb:["Keputusan hebat! Kamu menolak dengan tenang dan jelas. Bayu mungkin juga tidak tahu risikonya, jadi kamu tidak perlu menghakiminya.","Great decision! You refused calmly and clearly. Bayu may not know the risks either, so you do not need to judge him."]},
     {t:["Tanya dulu, \"Isinya apa?\", baru memutuskan.","Ask first, \"What's in it?\", then decide."],pts:10,
      fb:["Bertanya itu wajar, tetapi jawaban teman tidak bisa dipastikan benar, dan tanpa label atau resep dokter keamanannya tidak jelas. Cara paling aman: langsung menolak.","Asking is natural, but a friend's answer cannot be checked, and with no label or doctor's prescription its safety is unclear. The safest way is to refuse right away."]},
     {t:["Ambil satu supaya dia berhenti membujuk.","Take one so he stops asking."],pts:0,
      fb:["Wajar ingin cepat lepas dari bujukan, tetapi menerima benda tak dikenal bisa berisiko bagi kesehatanmu. Tidak apa-apa, coba lagi dan pilih jawaban yang menjaga keselamatanmu.","It is natural to want the pressure to stop, but accepting an unknown item can risk your health. That is okay, try again and choose an answer that protects your safety."]},
     {t:["Simpan di tas dulu, nanti dipikirkan.","Keep it in my bag and think about it later."],pts:0,
      fb:["Menyimpan benda yang tidak dikenal juga berisiko dan bisa menimbulkan masalah. Lebih baik jangan dibawa sama sekali.","Keeping an unknown item is risky too and can cause trouble. It is better not to carry it at all."]}],
    hint:["Kalau kamu tidak tahu persis isinya, jawabannya adalah tidak. Kamu tidak harus punya alasan panjang.","If you do not know exactly what it is, the answer is no. You do not need a long reason."],
    note:["Benda atau zat yang tidak dikenal tidak boleh dicoba, siapa pun yang menawarkan.","Never try an unknown item or substance, no matter who offers it."]},

  { title:["Bungkusan di Koridor","The Packet in the Corridor"], bg:"koridor", cast:["satpam"], type:"choice", cat:"safety",
    lines:[["nar",["Sepulang kelas, kamu melihat bungkusan kecil yang tidak dikenal tergeletak dekat loker.","After class, you see a small unknown packet on the floor near the lockers."]],
           ["me",["Hmm… punya siapa ini?","Hmm… whose is this?"]]],
    q:["Apa langkah pertamamu?","What is your first step?"],
    opts:[
     {t:["Tidak menyentuhnya. Aku mencari guru atau Pak Anto dan memberi tahu lokasinya.","I don't touch it. I find a teacher or Pak Anto and tell them where it is."],pts:20,
      fb:["Tepat! Kamu menjaga jarak dan segera memberi tahu orang dewasa.","Right! You kept your distance and told an adult straight away."],
      next:{lines:[["satpam",["Terima kasih sudah melapor, ya. Boleh tunjukkan dari jauh di mana tempatnya?","Thank you for reporting. Could you point out the spot from a distance?"]]],
        q:["Apa yang kamu lakukan sekarang?","What do you do now?"],
        opts:[
         {t:["Menunjukkan lokasinya dari jarak aman, lalu kembali ke kelas. Orang dewasa yang menangani.","Point out the spot from a safe distance, then go back to class. The adults handle it."],pts:20,
          fb:["Sempurna. Tugasmu selesai setelah melapor. Selanjutnya orang dewasa yang menangani.","Perfect. Your job is done once you report. The adults take it from here."]},
         {t:["Menunggu di dekat situ untuk melihat siapa yang mengambilnya.","Wait nearby to see who comes to pick it up."],pts:0,
          fb:["Mengawasi atau menyelidiki sendiri bisa membuatmu terlibat dalam situasi yang tidak aman. Itu tugas orang dewasa.","Watching or investigating on your own could put you in an unsafe situation. That is the adults' job."]},
         {t:["Bertanya ke teman-teman satu per satu, \"Ini punya siapa?\"","Ask classmates one by one, \"Is this yours?\""],pts:0,
          fb:["Menuduh atau menyelidiki bisa menyakiti orang yang tidak bersalah. Serahkan kepada guru.","Accusing or investigating can hurt innocent people. Leave it to the teachers."]},
         {t:["Menunjukkan lokasinya lalu menemani Pak Anto sampai guru datang.","Point out the spot, then stay with Pak Anto until a teacher arrives."],pts:10,
          fb:["Cukup baik karena kamu bersama orang dewasa, tetapi setelah melapor kamu boleh kembali ke kelas.","Fairly good because you are with an adult, but after reporting you may go back to class."]}]}},
     {t:["Tidak menyentuhnya, tetapi langsung pulang tanpa memberi tahu siapa pun.","I don't touch it, but I go home without telling anyone."],pts:10,
      fb:["Tidak menyentuh itu benar. Namun orang lain bisa menemukannya, jadi lebih baik beri tahu guru.","Not touching it is right. But someone else might find it, so it is better to tell a teacher."]},
     {t:["Membuka bungkusan itu untuk melihat isinya.","Open the packet to see what is inside."],pts:0,
      fb:["Membuka atau memegang benda tak dikenal tidak aman. Biarkan orang dewasa yang menangani. Coba lagi, ya!","Opening or touching an unknown item is not safe. Let adults handle it. Try again!"]},
     {t:["Mengambilnya dan membawanya ke kelas untuk ditanyakan ke teman.","Pick it up and bring it to class to ask my friends."],pts:0,
      fb:["Membawa benda itu ke kelas bisa membahayakan dirimu dan teman-temanmu. Lebih baik jangan disentuh.","Bringing it to class could put you and your friends at risk. It is better not to touch it."]}],
    hint:["Jangan sentuh, jangan buka, jangan selidiki. Cukup beri tahu orang dewasa.","Don't touch, don't open, don't investigate. Just tell an adult."],
    note:["Menemukan benda mencurigakan? Jangan sentuh, laporkan ke guru atau petugas sekolah.","Found something suspicious? Do not touch it, report it to a teacher or school staff."]},

  { title:["Tanda Bahaya di Seberang Sekolah","Warning Signs Across the Street"], bg:"sekolah", cast:["dito"], type:"select", cat:"safety", style:"chips",
    lines:[["dito",["Aku melihat ada penjual baru di seberang sekolah. Menurutmu, mana saja yang termasuk tanda bahaya?","I saw a new seller across the street from school. Which of these are warning signs, do you think?"]]],
    q:["Pilih semua tanda bahaya.","Choose all the warning signs."],
    items:[
     {t:["Barangnya tanpa label atau keterangan yang jelas.","The goods have no clear label or information."],ok:true,why:["Tanpa label, kamu tidak bisa tahu isi dan keamanannya.","Without a label you cannot know what is inside or whether it is safe."]},
     {t:["Penjual berkata, \"Jangan bilang ke guru atau orang tuamu, ya.\"","The seller says, \"Don't tell your teachers or parents.\""],ok:true,why:["Meminta merahasiakan dari orang dewasa adalah tanda bahaya besar.","Asking you to hide it from adults is a big warning sign."]},
     {t:["Katanya gratis khusus untukmu dan harus diterima sekarang.","They say it is free, just for you, and you must take it now."],ok:true,why:["Tawaran \"gratis\" yang terburu-buru sering dipakai untuk menekan.","A rushed \"free\" offer is often used to pressure people."]},
     {t:["Kantin sekolah menjual roti dengan harga yang tertulis jelas.","The school canteen sells bread with clear prices."],ok:false,why:["Ini normal dan terbuka, bukan tanda bahaya.","This is normal and open, not a warning sign."]},
     {t:["Ia terus membujuk walau kamu sudah menolak.","They keep pushing even after you say no."],ok:true,why:["Penolakanmu harus dihormati. Terus memaksa adalah tanda bahaya.","Your refusal should be respected. Pushing again and again is a warning sign."]},
     {t:["Ada banyak guru dan orang tua di sekitar gerbang.","Many teachers and parents are around the gate."],ok:false,why:["Ini justru membuat suasana lebih aman.","This actually makes the place safer."]}],
    hint:["Cari yang rahasia, terburu-buru, tanpa label, atau memaksa.","Look for secrecy, rush, missing labels, or pushing."],
    note:["Rahasia, terburu-buru, tanpa label, dan memaksa adalah tanda bahaya yang perlu kamu waspadai.","Secrecy, rush, no label and pushing are warning signs to watch for."]},

  { title:["Poster Tindakan Aman","The Safe Actions Poster"], bg:"kelas", cast:["guru"], type:"sort", cat:"safety",
    lines:[["guru",["Ayo bantu Bu Rina menyusun poster \"Tindakan Aman\". Tempatkan setiap kartu di kolom yang tepat!","Help Bu Rina make a \"Safe Actions\" poster. Put each card in the right column!"]]],
    q:["Tarik kartu ke kolom yang tepat, atau ketuk kartu lalu ketuk kolomnya.","Drag each card to the right column, or tap a card then tap the column."],
    bins:[["Aman","Safe"],["Tidak aman","Unsafe"]],
    items:[
     {t:["Menolak lalu menjauh","Say no and walk away"],bin:0},
     {t:["Memberi tahu orang dewasa tepercaya","Tell a trusted adult"],bin:0},
     {t:["Tetap dekat dengan guru atau teman yang baik","Stay close to teachers or good friends"],bin:0},
     {t:["Mencicipi sedikit untuk \"mengetes\"","Taste a little to \"test\" it"],bin:1,why:["Mencicipi benda tak dikenal tidak pernah aman.","Tasting an unknown item is never safe."]},
     {t:["Menerima karena yang menawari lebih tua","Accept because the person offering is older"],bin:1,why:["Umur seseorang tidak membuat tawarannya aman.","Someone's age does not make their offer safe."]},
     {t:["Menyimpan benda tak dikenal di tas","Keep an unknown item in my bag"],bin:1,why:["Lebih baik tidak membawa benda yang tidak kamu kenal.","It is better not to carry an item you do not know."]}],
    hint:["Tanyakan pada dirimu: apakah tindakan ini melindungiku?","Ask yourself: does this action protect me?"],
    note:["Tindakan aman: menolak, menjauh, dan memberi tahu orang dewasa tepercaya.","Safe actions: refuse, step away, and tell a trusted adult."]},

  { title:["Minuman Tanpa Label","The Unlabeled Drink"], bg:"rumah", cast:["nia"], type:"choice", cat:"safety",
    lines:[["nia",["Kamu masih bangun? Sepupuku bawa minuman tanpa label. Katanya rasanya enak dan bikin rileks. Boleh aku coba, nggak?","Are you awake? My cousin brought a drink with no label. He says it tastes nice and helps you relax. Can I try it?"]]],
    q:["Apa balasanmu untuk Nia?","What do you reply to Nia?"],
    opts:[
     {t:["Jangan diminum dulu ya, kita belum tahu isinya. Besok ceritakan ke orang tuamu atau gurumu, aku temani.","Please don't drink it, we don't know what is in it. Tomorrow tell your parents or a teacher, I'll go with you."],pts:20,
      fb:["Jawaban yang peduli dan aman! Kamu memberi saran jelas dan mengajak Nia mencari bantuan orang dewasa.","A caring and safe answer! You gave clear advice and encouraged Nia to ask an adult for help."]},
     {t:["Terserah kamu sih, tapi hati-hati ya.","Up to you, but be careful."],pts:10,
      fb:["Kamu peduli, tetapi jawabanmu belum jelas. Temanmu butuh saran yang tegas dan ajakan untuk bicara dengan orang dewasa.","You care, but your answer is not clear. Your friend needs firm advice and a push to talk to an adult."]},
     {t:["Boleh, coba sedikit saja.","Sure, try just a little."],pts:0,
      fb:["Sedikit pun bisa berisiko karena kita tidak tahu isinya. Coba lagi dan pilih jawaban yang melindungi Nia.","Even a little can be risky because we do not know what is in it. Try again and choose an answer that protects Nia."]},
     {t:["Aku ke rumahmu sekarang untuk menegur sepupumu.","I'll come over now to confront your cousin."],pts:0,
      fb:["Menghadapi orang lain sendirian tidak aman. Lebih baik minta bantuan orang dewasa.","Confronting someone alone is not safe. It is better to ask an adult for help."]}],
    hint:["Seorang sahabat yang baik berkata jelas \"jangan\" dan mengajak bicara dengan orang dewasa.","A good friend says a clear \"don't\" and suggests talking to an adult."],
    note:["Kamu bisa menolong teman dengan memberi saran jelas dan mengajaknya menemui orang dewasa tepercaya.","You can help a friend by giving clear advice and inviting them to see a trusted adult."]}
  ]},

/* ───────────────────────── MISSION 2 ───────────────────────── */
{ id:2, icon:"🗣️", badge:"voice", cat:"voice", mod:2, bg:"lapangan",
  title:["Tantangan Tekanan Teman","The Pressure Challenge"],
  place:["Halaman sekolah dan kegiatan ekstrakurikuler","Schoolyard and extracurricular activities"],
  mech:[["Penyusun dialog","Dialogue builder"],["Pilih respons","Choose the response"],["Keputusan bercabang","Branching decisions"]],
  intro:["Teman bisa mengajak ke hal baik, tapi kadang ajakannya menekan. Saatnya melatih suara beranimu!","Friends can invite you to good things, but sometimes invitations feel like pressure. Time to practise your brave voice!"],
  reward:["Lencana Suara Berani","Brave Voice Badge"],
  rewardDesc:["Kamu berani menolak dengan jelas, tenang, dan sopan.","You can say no clearly, calmly and politely."],
  scenes:[
  { title:["Ajakan Bolos","The Skipping Invitation"], bg:"lapangan", cast:["bayu"], type:"build", cat:"voice",
    lines:[["bayu",["Hei, katanya kamu pemberani? Ikut kami bolos ke belakang gedung, yuk. Semua ikut!","Hey, I heard you're brave. Come skip class with us behind the building. Everyone's going!"]]],
    q:["Susun jawabanmu dalam tiga bagian.","Build your reply in three parts."],
    steps:[
     {label:["1. Katakan \"tidak\" dengan jelas","1. Say \"no\" clearly"],opts:[
       {t:["Tidak, terima kasih. Aku tidak mau.","No, thank you. I don't want to."],ok:true},
       {t:["Hmm… mungkin lain kali.","Hmm… maybe next time."],ok:false,why:["\"Mungkin\" membuka pintu untuk bujukan berikutnya.","\"Maybe\" leaves the door open for more pressure."]},
       {t:["Ya sudah, cuma sebentar.","Okay, just for a little while."],ok:false,why:["Itu berarti kamu setuju. Coba katakan tidak dengan jelas.","That means you agree. Try saying no clearly."]}]},
     {label:["2. Beri alasan atau ajakan lain","2. Give a reason or an alternative"],opts:[
       {t:["Aku lebih suka latihan basket di lapangan. Mau ikut?","I'd rather practise basketball on the court. Want to join?"],ok:true},
       {t:["Kalian payah banget sih!","You guys are so lame!"],ok:false,why:["Kata kasar bisa memicu pertengkaran. Tegas tidak harus kasar.","Harsh words can start a fight. Being firm does not mean being rude."]},
       {t:["Aku ikut, tapi nggak ngapa-ngapain.","I'll come, but I won't do anything."],ok:false,why:["Ikut berarti tetap berada dalam situasi yang menekan.","Going along keeps you in the pressure situation."]}]},
     {label:["3. Kalau mereka terus memaksa","3. If they keep pushing"],opts:[
       {t:["Tolong jangan paksa aku. Aku harus pergi sekarang.","Please don't pressure me. I need to leave now."],ok:true},
       {t:["Baiklah, kalian menang.","Fine, you win."],ok:false,why:["Menyerah berarti pilihanmu diabaikan.","Giving in means your choice is ignored."]},
       {t:["Diam saja dan ikuti mereka.","Say nothing and follow them."],ok:false,why:["Diam bisa dianggap setuju. Ucapkan pilihanmu.","Silence can look like agreement. Say what you choose."]}]}],
    hint:["Suara tegas, tenang, dan sopan: tolak, beri alternatif, lalu pergi.","A firm, calm, polite voice: refuse, offer an alternative, then leave."],
    note:["Menolak dengan tegas tapi sopan: katakan tidak, tawarkan alternatif, lalu pergi bila terus dipaksa.","Refuse firmly but politely: say no, offer an alternative, then leave if pushed."]},

  { title:["\"Nanti Kita Dijauhi\"","\"They'll Leave Us Out\""], bg:"kelas", cast:["dito"], type:"choice", cat:"voice",
    lines:[["dito",["Kalau kita menolak, nanti Bayu dan gengnya menjauhi kita, lho. Aku takut sendirian.","If we say no, Bayu and his group might stay away from us. I'm scared of being alone."]]],
    q:["Apa yang kamu katakan pada Dito?","What do you say to Dito?"],
    opts:[
     {t:["Teman yang baik menghormati pilihan kita. Yuk gabung klub seni atau basket supaya punya teman baru.","Good friends respect our choices. Let's join the art or basketball club and make new friends."],pts:20,
      fb:["Mantap! Kamu menenangkan Dito dan menunjukkan jalan keluar yang positif.","Great! You reassured Dito and showed a positive way forward."]},
     {t:["Kita menjauh saja dari semua orang.","Let's just stay away from everyone."],pts:10,
      fb:["Rasa takutnya bisa dimengerti, tetapi menjauh dari semua orang justru membuat kalian kesepian. Cari teman dan kegiatan yang positif.","His fear is understandable, but staying away from everyone makes you lonelier. Look for positive friends and activities."]},
     {t:["Kamu benar, ikut sekali saja supaya aman dari mereka.","You're right, let's go along just once to stay on their good side."],pts:0,
      fb:["Ikut sekali sering menjadi awal tekanan berikutnya. Kamu berhak berkata tidak. Coba lagi!","Going along once often leads to more pressure. You have the right to say no. Try again!"]},
     {t:["Kamu saja yang ikut mereka, aku tidak peduli.","You go with them, I don't care."],pts:0,
      fb:["Dito sedang butuh dukungan. Menolak bersama teman membuat kalian lebih kuat.","Dito needs support right now. Saying no together makes you both stronger."]}],
    hint:["Berani menolak lebih mudah kalau punya teman dan kegiatan yang positif.","Saying no is easier when you have positive friends and activities."],
    note:["Teman sejati menghormati keputusanmu. Kamu bisa menemukan lingkungan yang positif.","True friends respect your decisions. You can find a positive circle."]},

  { title:["Buktikan Beranimu!","Prove You're Brave!"], bg:"lapangan", cast:["bayu"], type:"choice", cat:"voice",
    lines:[["nar",["Di belakang sekolah, sekelompok siswa berkumpul dekat pagar.","Behind the school, a group of students gathers near the fence."]],
           ["bayu",["Kalau kamu berani, panjat pagar belakang ini dan keluar sebentar. Buktikan dong!","If you're brave, climb the back fence and go out for a while. Prove it!"]]],
    q:["Bagaimana jawabanmu?","How do you answer?"],
    opts:[
     {t:["Aku tidak perlu membuktikan apa pun. Aturan sekolah ada untuk menjaga kita.","I don't need to prove anything. School rules are there to keep us safe."],pts:20,
      fb:["Berani itu bukan soal melanggar aturan, tetapi soal mempertahankan pilihan yang benar.","Being brave is not about breaking rules, it is about standing by a good choice."],
      next:{lines:[["bayu",["Huh, penakut!","Huh, chicken!"]],["nar",["Beberapa anak tertawa.","A few students laugh."]]],
        q:["Apa yang kamu lakukan?","What do you do?"],
        opts:[
         {t:["Tersenyum, \"Terserah kalian menyebutku apa. Pilihanku tetap sama.\" Lalu pergi ke perpustakaan.","Smile and say, \"Call me what you like. My choice stays the same.\" Then head to the library."],pts:20,
          fb:["Kamu tetap tenang dan memilih lingkungan yang positif. Hebat!","You stayed calm and chose a positive place. Excellent!"]},
         {t:["Berteriak dan mendorong Bayu.","Shout and push Bayu."],pts:0,
          fb:["Kekerasan membuat masalah jadi lebih besar. Ucapan tenang dan menjauh jauh lebih kuat.","Violence makes the problem bigger. A calm voice and walking away are much stronger."]},
         {t:["Minta maaf dan bilang akan memanjat besok.","Say sorry and promise to climb tomorrow."],pts:0,
          fb:["Menunda tidak menyelesaikan tekanan, dan melanggar aturan tetap tidak aman.","Delaying does not solve the pressure, and breaking the rule is still unsafe."]},
         {t:["Diam saja dan menjauh tanpa bicara.","Say nothing and walk away."],pts:10,
          fb:["Menjauh itu bagus. Menambahkan satu kalimat tegas akan membuat sikapmu lebih jelas.","Walking away is good. Adding one firm sentence would make your stand clearer."]}]}},
     {t:["Panjat cepat saja, supaya mereka diam.","Climb quickly so they stop."],pts:0,
      fb:["Melanggar aturan demi diterima bisa membahayakanmu. Tidak apa-apa, coba lagi!","Breaking rules to fit in can put you in danger. That is okay, try again!"]},
     {t:["Bercanda dan mengalihkan topik ke pertandingan sore ini.","Make a joke and change the subject to this afternoon's match."],pts:10,
      fb:["Mengalihkan topik bisa membantu, tetapi sebaiknya tegaskan juga bahwa kamu tidak mau.","Changing the subject can help, but also make clear that you don't want to."]},
     {t:["Bilang \"oke\", tapi lihat dulu apakah ada guru.","Say \"okay\", but check first whether a teacher is around."],pts:0,
      fb:["Menghindari ketahuan bukan alasan yang baik. Pagar dan aturan dibuat untuk keselamatan.","Avoiding getting caught is not a good reason. Fences and rules exist for safety."]}],
    hint:["Keberanian sejati: mempertahankan pilihan yang aman meski ditertawakan.","True courage: sticking with a safe choice even when others laugh."],
    note:["Kamu tidak perlu membuktikan apa-apa dengan melanggar aturan.","You do not have to prove anything by breaking rules."]},

  { title:["Grup Chat \"Geng Keren\"","The \"Cool Crew\" Group Chat"], bg:"rumah", cast:["nia"], type:"choice", cat:"voice",
    lines:[["phone",["Grup \"Geng Keren\": Yang datang ke belakang kantin sepulang sekolah itu keren. Yang nggak datang… ya terserah.","\"Cool Crew\" group: Anyone who comes behind the canteen after school is cool. Those who don't… well, up to you."]],
           ["nia",["Kamu mau datang? Aku bingung mau balas apa…","Are you going? I don't know what to reply…"]]],
    q:["Kamu membalas apa di grup?","What do you reply in the group?"],
    opts:[
     {t:["Aku tidak ikut ya, aku ada kegiatan lain. Sampai besok!","I won't come, I have other plans. See you tomorrow!"],pts:20,
      fb:["Singkat, jelas, dan sopan. Itu contoh penolakan yang baik.","Short, clear and polite. That is a great example of refusing."]},
     {t:["Tidak membalas sama sekali.","Don't reply at all."],pts:10,
      fb:["Tidak ikut itu sudah tepat, tetapi menjawab singkat akan membuat sikapmu lebih jelas dan mengurangi tekanan.","Not going is right, but a short reply makes your stand clear and reduces the pressure."]},
     {t:["Oke, aku datang.","Okay, I'll come."],pts:0,
      fb:["Ajakan yang tidak jelas tujuannya patut diwaspadai. Kamu boleh menolak. Coba lagi!","An invitation with an unclear purpose deserves caution. You may refuse. Try again!"]},
     {t:["Membalas dengan marah dan kata-kata kasar.","Reply angrily with rude words."],pts:0,
      fb:["Kemarahan bisa memperkeruh keadaan. Ketegasan yang tenang lebih efektif.","Anger can make things worse. Calm firmness works better."]}],
    hint:["Balasan yang bagus: singkat, jelas, sopan, tanpa harus berdebat.","A good reply is short, clear and polite, without arguing."],
    note:["Menolak lewat pesan pun boleh, cukup singkat, jelas, dan sopan.","You can also refuse by message: just keep it short, clear and polite."]},

  { title:["Kalimat Penolakan Tegas","Firm Refusal Phrases"], bg:"sekolah", cast:["guru"], type:"select", cat:"voice", style:"chips",
    lines:[["guru",["Mari pilih kalimat yang menolak dengan tegas tapi tetap sopan. Pilih semua yang tepat!","Let's pick the sentences that refuse firmly but still politely. Choose all that fit!"]]],
    q:["Mana kalimat penolakan yang tegas dan sopan?","Which sentences refuse firmly and politely?"],
    items:[
     {t:["Tidak, terima kasih.","No, thank you."],ok:true},
     {t:["Aku tidak tertarik.","I'm not interested."],ok:true},
     {t:["Tolong jangan paksa aku.","Please don't pressure me."],ok:true},
     {t:["Aku harus pergi sekarang.","I need to leave now."],ok:true},
     {t:["Mmm… mungkin… entahlah…","Umm… maybe… I don't know…"],ok:false,why:["Jawaban ragu-ragu mengundang bujukan lagi.","A hesitant answer invites more pushing."]},
     {t:["Kalian semua bodoh!","You are all stupid!"],ok:false,why:["Menghina bukan ketegasan. Tolak tanpa menyakiti.","Insults are not assertiveness. Refuse without hurting."]},
     {t:["Oke deh, asal kalian jangan marah.","Okay then, as long as you don't get mad."],ok:false,why:["Itu berarti kamu menyerah pada tekanan.","That means giving in to the pressure."]}],
    hint:["Ciri kalimat tegas: jelas, tenang, sopan, dan tidak ragu.","A firm sentence is clear, calm, polite and not hesitant."],
    note:["Kalimat tegas tidak perlu kasar. Kamu berhak berkata tidak.","Firm sentences do not need to be rude. You have the right to say no."]}
  ]},

/* ───────────────────────── MISSION 3 ───────────────────────── */
{ id:3, icon:"📱", badge:"smart", cat:"safety", mod:3, bg:"rumah",
  title:["Pesan Rahasia","The Secret Message"],
  place:["Dunia digital dan keseharian","Digital life and everyday situations"],
  mech:[["Simulasi pesan","Message simulation"],["Temukan tanda bahaya","Spot the red flags"],["Tantangan keputusan","Decision challenge"]],
  intro:["Ponselmu bergetar. Ada pesan aneh yang menyuruhmu merahasiakan sesuatu. Waspada dan cari bantuan!","Your phone buzzes. A strange message asks you to keep something secret. Stay alert and get help!"],
  reward:["Lencana Keputusan Cerdas","Smart Decision Badge"],
  rewardDesc:["Kamu cerdas mengenali tanda bahaya dan tahu kapan harus meminta bantuan.","You are smart at spotting red flags and know when to ask for help."],
  scenes:[
  { title:["Pesan dari Nomor Asing","A Message from an Unknown Number"], bg:"rumah", cast:[], type:"select", cat:"safety", style:"chat",
    lines:[["nar",["Ponselmu bergetar. Ada pesan dari nomor yang tidak kamu kenal.","Your phone buzzes. A message from a number you don't know."]]],
    q:["Ketuk pesan yang merupakan tanda bahaya (🚩).","Tap the messages that are red flags (🚩)."],
    from:["Nomor tak dikenal","Unknown number"],
    items:[
     {t:["Selamat sore.","Good afternoon."],ok:false,why:["Sapaan biasa, belum tentu bahaya.","A normal greeting, not a red flag by itself."]},
     {t:["Hai! Aku temannya kakakmu 😊","Hi! I'm a friend of your brother 😊"],ok:true,why:["Kamu tidak mengenalnya. Orang asing sering mengaku kenal.","You do not know them. Strangers often claim to know you."]},
     {t:["Bisa antar bungkusan kecil ke gerbang belakang sepulang sekolah? Upahnya Rp100.000!","Can you deliver a small package to the back gate after school? You'll get Rp100,000!"],ok:true,why:["Mengantar bungkusan tak dikenal dengan upah besar itu mencurigakan.","Carrying an unknown package for a big reward is suspicious."]},
     {t:["Jangan kasih tahu siapa pun, termasuk orang tuamu ya.","Don't tell anyone, not even your parents."],ok:true,why:["Merahasiakan dari orang tua adalah tanda bahaya utama.","Hiding it from your parents is a major red flag."]},
     {t:["Balas SEKARANG, aku menunggu!","Reply NOW, I'm waiting!"],ok:true,why:["Memaksamu cepat-cepat agar kamu tidak sempat berpikir.","Rushing you so you have no time to think."]},
     {t:["Terima kasih sudah membaca pesanku.","Thanks for reading my message."],ok:false,why:["Kalimat sopan biasa, bukan tanda bahaya.","A normal polite sentence, not a red flag."]}],
    hint:["Waspadai orang asing, hadiah besar, rahasia dari orang tua, dan desakan cepat.","Watch for strangers, big rewards, secrets from parents, and rush."],
    note:["Orang asing, imbalan besar, rahasia, dan desakan cepat adalah kombinasi tanda bahaya.","Strangers, big rewards, secrecy and rush make a combination of red flags."]},

  { title:["Apa Langkah Selanjutnya?","What Happens Next?"], bg:"rumah", cast:["ortu"], type:"choice", cat:"safety",
    lines:[["nar",["Pesan itu masih ada di layar ponselmu. Ibu duduk di sebelahmu sedang membaca buku.","The message is still on your screen. Mum is sitting next to you reading a book."]]],
    q:["Apa yang kamu lakukan dengan pesan itu?","What do you do with the message?"],
    opts:[
     {t:["Tidak membalas, lalu menunjukkan pesan itu kepada Ibu.","Don't reply, and show the message to Mum."],pts:20,
      fb:["Tepat! Orang dewasa tepercaya bisa membantumu menilai dan melindungi keluarga.","Right! A trusted adult can help you judge it and keep your family safe."]},
     {t:["Menghapus pesan dan melupakannya.","Delete the message and forget it."],pts:10,
      fb:["Tidak membalas itu baik, tetapi orang dewasa perlu tahu agar bisa melindungimu dan orang lain.","Not replying is good, but an adult needs to know so they can protect you and others."]},
     {t:["Membalas, \"Kamu siapa?\"","Reply, \"Who are you?\""],pts:0,
      fb:["Membalas memberi tahu mereka bahwa nomormu aktif dan bisa membuat mereka terus menghubungi. Coba lagi!","Replying tells them your number is active and they may keep contacting you. Try again!"]},
     {t:["Datang ke gerbang belakang untuk mengintip.","Go to the back gate to peek."],pts:0,
      fb:["Mendatangi tempat itu berbahaya. Jangan menyelidiki sendiri, serahkan kepada orang dewasa.","Going there is dangerous. Do not investigate on your own, leave it to adults."]}],
    hint:["Pesan yang menyuruh merahasiakan sesuatu justru harus kamu tunjukkan kepada orang dewasa.","A message that asks for secrecy is exactly the one you should show an adult."],
    note:["Jangan balas, jangan datangi, dan tunjukkan kepada orang dewasa tepercaya.","Do not reply, do not go there, and show it to a trusted adult."]},

  { title:["Titip Tas","Keep This Bag"], bg:"koridor", cast:["bayu"], type:"choice", cat:"safety",
    lines:[["bayu",["Titip tas ini di lokermu sebentar, ya. Jangan dibuka dan jangan bilang siapa-siapa.","Keep this bag in your locker for a while. Don't open it, and don't tell anyone."]]],
    q:["Apa jawabanmu?","What is your answer?"],
    opts:[
     {t:["Maaf, aku tidak bisa menyimpan barang yang tidak kuketahui isinya.","Sorry, I can't keep something when I don't know what's in it."],pts:20,
      fb:["Jelas, sopan, dan aman. Kamu melindungi dirimu dari masalah.","Clear, polite and safe. You protected yourself from trouble."]},
     {t:["Menolak, lalu pergi tanpa memberi tahu siapa pun.","Refuse, then leave without telling anyone."],pts:10,
      fb:["Menolak sudah tepat. Jika ada yang mengkhawatirkan, ceritakan kepada guru agar mereka bisa membantu.","Refusing is right. If something worries you, tell a teacher so they can help."]},
     {t:["Oke, asal tidak kubuka.","Okay, as long as I don't open it."],pts:0,
      fb:["Menyimpan barang yang tidak kamu tahu isinya bisa menyeretmu ke masalah. Coba lagi!","Keeping something you know nothing about can pull you into trouble. Try again!"]},
     {t:["Membuka tasnya dulu untuk mengecek.","Open the bag first to check."],pts:0,
      fb:["Memegang atau membuka barang yang tidak jelas tidak aman. Lebih baik tolak.","Handling or opening an unclear item is not safe. It is better to refuse."]}],
    hint:["Barang titipan dan rahasia: tolak, lalu ceritakan ke guru bila kamu khawatir.","A secret bag to hold: refuse, then tell a teacher if you are worried."],
    note:["Jangan menyimpan atau membawa barang tak dikenal untuk orang lain.","Do not keep or carry unknown items for someone else."]},

  { title:["Teman Baru di Gim","A New Friend in the Game"], bg:"rumah", cast:["ortu"], type:"choice", cat:"voice",
    lines:[["nar",["Saat bermain gim daring, pemain baru bernama \"Rex\" mengobrol denganmu.","While playing an online game, a new player called \"Rex\" chats with you."]],
           ["game",["Kamu hebat! Aku mau kirim hadiah. Boleh minta alamat rumah dan nama sekolahmu? Rahasiakan dari orang tuamu ya.","You're great! I want to send you a gift. Can I have your home address and school name? Keep it secret from your parents."]]],
    q:["Apa yang kamu lakukan?","What do you do?"],
    opts:[
     {t:["Tidak memberi data apa pun dan menunjukkan obrolan itu kepada Ibu.","Give no details and show the chat to Mum."],pts:20,
      fb:["Hebat! Menjaga data pribadi dan bercerita kepada orang tua adalah langkah yang tepat.","Excellent! Protecting your personal data and telling a parent is the right step."],
      next:{lines:[["ortu",["Terima kasih sudah cerita, Nak. Menurutmu, apa yang sebaiknya kita simpan sebagai bukti?","Thank you for telling me. What do you think we should keep as evidence?"]]],
        q:["Apa usulmu?","What do you suggest?"],
        opts:[
         {t:["Tangkapan layar obrolan, lalu kita tanyakan ke guru atau pihak yang tepat.","Screenshots of the chat, then we ask a teacher or the right authority."],pts:20,
          fb:["Bagus! Bukti yang tersimpan membantu orang dewasa mengambil langkah yang tepat.","Good! Saved evidence helps adults take the right steps."]},
         {t:["Hapus obrolannya supaya tidak ada yang tahu.","Delete the chat so nobody finds out."],pts:0,
          fb:["Menghapus bisa menghilangkan bukti penting. Simpan dan tunjukkan kepada orang dewasa.","Deleting can erase important evidence. Keep it and show it to adults."]},
         {t:["Membalas dengan marah dan mengancamnya.","Reply angrily and threaten him."],pts:0,
          fb:["Mengancam bisa memperburuk keadaan. Biarkan orang dewasa yang menanganinya.","Threatening can make it worse. Let adults handle it."]},
         {t:["Memblokir akunnya saja.","Just block the account."],pts:10,
          fb:["Memblokir itu baik, tetapi tetap simpan bukti dan laporkan agar anak lain terlindungi.","Blocking is good, but also keep the evidence and report so other kids are protected."]}]}},
     {t:["Memberi nama sekolah saja, alamat tidak.","Share only the school name, not the address."],pts:0,
      fb:["Nama sekolah pun termasuk data pribadi yang bisa dipakai untuk melacakmu. Coba lagi!","Even the school name is personal data that can be used to find you. Try again!"]},
     {t:["Memblokir akunnya tanpa memberi tahu siapa pun.","Block the account without telling anyone."],pts:10,
      fb:["Memblokir itu langkah baik, tetapi orang dewasa tetap perlu tahu.","Blocking is a good step, but an adult still needs to know."]},
     {t:["Mengobrol lebih lama untuk mencari tahu siapa dia.","Keep chatting to find out who he is."],pts:0,
      fb:["Jangan menyelidiki orang asing sendiri. Itu berisiko.","Do not investigate strangers on your own. It is risky."]}],
    hint:["Jangan berikan data pribadi kepada orang asing, dan ceritakan kepada orang tua.","Never give personal data to strangers, and tell a parent."],
    note:["Lindungi data pribadi, simpan bukti, dan minta bantuan orang dewasa.","Protect personal data, keep evidence, and ask adults for help."]},

  { title:["Pasangkan Situasi dan Tindakan","Match the Situation to the Action"], bg:"koridor", cast:["guru"], type:"match", cat:"safety",
    lines:[["guru",["Mari kita uji kemampuanmu! Pasangkan setiap situasi dengan tindakan yang paling aman.","Let's test your skills! Match each situation with the safest action."]]],
    q:["Ketuk satu situasi, lalu ketuk tindakan yang cocok.","Tap a situation, then tap the action that fits."],
    pairs:[
     {a:["Orang asing meminta alamat rumahmu","A stranger asks for your home address"],b:["Jangan beri; ceritakan ke orang tua","Don't share it; tell a parent"]},
     {a:["Seseorang menyuruhmu mengantar paket tak dikenal","Someone asks you to carry an unknown package"],b:["Tolak dan laporkan ke guru","Say no and tell a teacher"]},
     {a:["Pesan menyuruhmu merahasiakan sesuatu dari orang tua","A message tells you to hide something from your parents"],b:["Tunjukkan ke orang dewasa tepercaya","Show it to a trusted adult"]},
     {a:["Temanmu menerima tawaran aneh dan bingung","A friend gets a strange offer and feels unsure"],b:["Ajak bicara dengan guru BK","Invite them to talk to the counselor"]}],
    hint:["Setiap jawaban melibatkan menolak, menjaga data, dan memberi tahu orang dewasa.","Every answer involves refusing, protecting data, and telling an adult."],
    note:["Menolak, melindungi data pribadi, dan melapor kepada orang dewasa adalah tiga kunci keamananmu.","Refusing, protecting personal data and telling an adult are your three safety keys."]}
  ]},

/* ───────────────────────── MISSION 4 ───────────────────────── */
{ id:4, icon:"💛", badge:"caring", cat:"empathy", mod:3, bg:"konseling",
  title:["Sahabat Butuh Bantuan","A Friend Needs Help"],
  place:["Ruang kelas dan ruang BK","Classroom and counseling room"],
  mech:[["Percakapan interaktif","Interactive conversation"],["Tantangan empati","Empathy challenge"],["Pilih respons yang mendukung","Choose the supportive response"]],
  intro:["Dito tampak diam dan cemas. Jangan menebak-nebak. Dengarkan dengan hati dan bantu dengan cara yang tepat.","Dito seems quiet and worried. Don't guess. Listen with care and help in the right way."],
  reward:["Lencana Pahlawan Peduli","Caring Hero Badge"],
  rewardDesc:["Kamu mendengarkan tanpa menghakimi dan membantu teman mencari dukungan.","You listen without judging and help friends find support."],
  scenes:[
  { title:["Dito yang Pendiam","Quiet Dito"], bg:"kelas", cast:["dito"], type:"choice", cat:"empathy",
    lines:[["nar",["Dito biasanya ceria, tetapi hari ini ia diam dan tidak menyentuh bekalnya.","Dito is usually cheerful, but today he is quiet and has not touched his lunch."]]],
    q:["Apa yang kamu katakan?","What do you say?"],
    opts:[
     {t:["Aku lihat kamu agak diam hari ini. Aku di sini kalau kamu mau cerita.","I noticed you're a bit quiet today. I'm here if you want to talk."],pts:20,
      fb:["Kamu hadir tanpa menebak-nebak dan tanpa memaksa. Itu dukungan yang menenangkan.","You were present without guessing or pushing. That is calming support."]},
     {t:["Sudahlah, jangan sedih. Semangat!","Come on, don't be sad. Cheer up!"],pts:10,
      fb:["Niatnya baik, tetapi perasaan Dito perlu didengar dulu sebelum dihibur.","Your intention is kind, but Dito's feelings need to be heard before cheering up."]},
     {t:["Kamu kenapa? Jangan-jangan kamu pakai sesuatu, ya?","What's wrong with you? Are you on something?"],pts:0,
      fb:["Menebak-nebak tanpa bukti bisa menyakitkan dan keliru. Perubahan sikap punya banyak sebab: lelah, sedih, atau masalah di rumah.","Guessing without evidence can hurt and be wrong. Mood changes have many causes: tiredness, sadness or trouble at home."]},
     {t:["Memberi tahu seluruh kelas bahwa Dito aneh hari ini.","Tell the whole class that Dito is acting weird today."],pts:0,
      fb:["Menyebarkan hal tentang teman bisa mempermalukannya. Peduli artinya menjaga privasinya.","Spreading things about a friend can embarrass him. Caring means protecting his privacy."]}],
    hint:["Mulailah dengan mengamati dan menawarkan diri mendengarkan, bukan menuduh.","Start by noticing and offering to listen, not accusing."],
    note:["Jangan berasumsi. Perubahan sikap tidak otomatis berarti masalah narkoba.","Do not assume. A change in mood does not automatically mean drug use."]},

  { title:["\"Aku Cuma Capek…\"","\"I'm Just Tired…\""], bg:"konseling", cast:["dito"], type:"choice", cat:"empathy",
    lines:[["dito",["Aku cuma capek… semuanya terasa terlalu banyak. Tugas, ujian, dan di rumah juga ramai.","I'm just tired… everything feels like too much. Homework, tests, and it's noisy at home too."]]],
    q:["Bagaimana kamu menanggapi?","How do you respond?"],
    opts:[
     {t:["Kedengarannya berat ya. Terima kasih sudah cerita padaku. Aku dengarkan.","That sounds hard. Thank you for telling me. I'm listening."],pts:20,
      fb:["Kamu mendengarkan dan menghargai kepercayaannya.","You listened and valued his trust."],
      next:{lines:[["dito",["Aku nggak tahu harus bagaimana…","I don't know what to do…"]]],
        q:["Dito ragu. Apa yang kamu tawarkan?","Dito hesitates. What do you offer?"],
        opts:[
         {t:["Bagaimana kalau kita bicara dengan Bu Dewi, guru BK? Aku temani, dan kamu yang memutuskan kapan.","How about we talk to Bu Dewi, the counselor? I'll go with you, and you decide when."],pts:20,
          fb:["Kamu menawarkan bantuan sambil menghormati pilihannya. Itu keseimbangan yang tepat.","You offered help while respecting his choice. That is the right balance."]},
         {t:["Mengajak jalan santai ke lapangan supaya ia lebih tenang.","Invite him for a relaxed walk on the field so he calms down."],pts:10,
          fb:["Bagus untuk menenangkan, tetapi ajak juga ia bicara dengan guru BK.","Good for calming down, but also encourage him to talk to the counselor."]},
         {t:["Aku janji akan merahasiakan semuanya, apa pun yang terjadi.","I promise to keep everything secret, no matter what."],pts:0,
          fb:["Jangan berjanji merahasiakan jika keselamatannya terancam. Orang dewasa tepercaya perlu membantu.","Don't promise secrecy if his safety is at risk. A trusted adult needs to help."]},
         {t:["Sudah, tidur saja, nanti juga hilang.","Just sleep it off, it will pass."],pts:0,
          fb:["Perasaan kewalahan butuh didengar, bukan diabaikan.","Feeling overwhelmed needs to be heard, not brushed off."]}]}},
     {t:["Semua orang juga stres. Jangan lebay.","Everyone gets stressed. Don't overreact."],pts:0,
      fb:["Kalimat ini meremehkan perasaannya. Coba dengarkan dulu dengan hangat.","This dismisses his feelings. Try listening warmly first."]},
     {t:["Ajak dia jalan-jalan sebentar tanpa bertanya apa pun.","Take him for a short walk without asking anything."],pts:10,
      fb:["Kehadiranmu menenangkan, tetapi beri juga ruang agar ia bisa bercerita.","Your presence is calming, but also give him space to talk."]},
     {t:["Kamu cuma kurang kuat. Coba lebih keras.","You're just not strong enough. Try harder."],pts:0,
      fb:["Menyalahkan membuat orang menutup diri. Dukungan yang hangat jauh lebih membantu.","Blaming makes people close up. Warm support helps much more."]}],
    hint:["Dengarkan dulu, hargai kepercayaan, lalu tawarkan menemani bicara dengan orang dewasa.","Listen first, value the trust, then offer to go with him to an adult."],
    note:["Mendengarkan tanpa menghakimi, lalu mengajak bicara dengan guru BK, adalah dukungan yang baik.","Listening without judging, then inviting him to talk to the counselor, is good support."]},

  { title:["Kata-Kata yang Mendukung","Supportive Words"], bg:"konseling", cast:["konselor"], type:"select", cat:"empathy", style:"chips",
    lines:[["konselor",["Bagus kamu peduli pada temanmu. Menurutmu, mana saja respons yang mendukung?","It's good that you care about your friend. Which responses are supportive, do you think?"]]],
    q:["Pilih semua respons yang mendukung.","Choose all the supportive responses."],
    items:[
     {t:["Aku di sini untuk mendengarkan.","I'm here to listen."],ok:true},
     {t:["Terima kasih sudah percaya padaku.","Thank you for trusting me."],ok:true},
     {t:["Mau kutemani bicara dengan guru?","Would you like me to come with you to talk to a teacher?"],ok:true},
     {t:["Aku sudah tahu kamu kenapa. Pasti karena kamu begini dan begitu.","I already know what's wrong. It must be because of this and that."],ok:false,why:["Menebak-nebak membuat temanmu merasa dihakimi.","Guessing makes your friend feel judged."]},
     {t:["Sudahlah, jangan lebay.","Come on, don't overreact."],ok:false,why:["Kalimat ini meremehkan perasaannya.","This dismisses his feelings."]},
     {t:["Ceritakan padaku saja dan jangan pernah ke orang dewasa.","Tell only me and never tell an adult."],ok:false,why:["Orang dewasa tepercaya bisa membantu hal yang tidak bisa kamu tangani sendiri.","Trusted adults can help with things you cannot handle alone."]}],
    hint:["Respons yang mendukung mendengarkan, menghargai, dan menawarkan bantuan, bukan menebak.","Supportive responses listen, value and offer help, not guess."],
    note:["Dukung temanmu dengan mendengarkan, berterima kasih atas kepercayaannya, dan menemaninya mencari bantuan.","Support your friend by listening, thanking them for trust, and going with them to seek help."]},

  { title:["Mitos atau Fakta?","Myth or Fact?"], bg:"kelas", cast:["guru"], type:"mcq", cat:"empathy",
    lines:[["guru",["Tidak semua perubahan sikap berarti masalah narkoba. Yuk, cek mana yang mitos dan mana yang fakta!","Not every change in mood means a drug problem. Let's check what is myth and what is fact!"]]],
    q:["Mitos atau fakta?","Myth or fact?"],
    items:[
     {q:["Kalau teman jadi pendiam, pasti dia memakai narkoba.","If a friend becomes quiet, they must be using drugs."],opts:MF,ok:0,why:["Mitos. Diam bisa karena lelah, sedih, atau masalah lain. Jangan berasumsi.","Myth. Quietness can come from tiredness, sadness or other problems. Don't assume."]},
     {q:["Perubahan sikap bisa punya banyak penyebab, seperti stres, kurang tidur, atau masalah keluarga.","Changes in behaviour can have many causes, like stress, lack of sleep or family problems."],opts:MF,ok:1,why:["Fakta. Karena itu kita mendengarkan, bukan menuduh.","Fact. That is why we listen instead of accusing."]},
     {q:["Menyelidiki sendiri teman yang dicurigai adalah cara terbaik membantu.","Investigating a suspected friend on your own is the best way to help."],opts:MF,ok:0,why:["Mitos. Menyelidiki sendiri bisa berbahaya. Minta bantuan orang dewasa.","Myth. Investigating alone can be dangerous. Ask adults for help."]},
     {q:["Guru BK dan orang dewasa tepercaya dapat membantu ketika keselamatan teman terancam.","Counselors and trusted adults can help when a friend's safety is at risk."],opts:MF,ok:1,why:["Fakta. Meminta bantuan mereka adalah tindakan yang peduli.","Fact. Asking them for help is a caring action."]},
     {q:["Membicarakan masalah teman dengan banyak orang membantunya.","Talking about a friend's problems with many people helps them."],opts:MF,ok:0,why:["Mitos. Menggosip menyakiti dan membuat teman takut meminta tolong.","Myth. Gossip hurts and makes friends afraid to ask for help."]}],
    hint:["Ingat: dengarkan, jangan menuduh, dan jangan menyelidiki sendiri.","Remember: listen, don't accuse, and don't investigate alone."],
    note:["Jangan menyimpulkan terlalu cepat. Empati dan bantuan orang dewasa lebih penting daripada tebakan.","Don't jump to conclusions. Empathy and adult help matter more than guesses."]},

  { title:["Ada yang Menekan Dito","Someone Is Pressuring Dito"], bg:"konseling", cast:["dito"], type:"choice", cat:"empathy",
    lines:[["dito",["Ada seseorang yang terus memaksaku mencoba sesuatu, dan aku takut. Tolong jangan bilang siapa-siapa…","Someone keeps pushing me to try something, and I'm scared. Please don't tell anyone…"]]],
    q:["Apa yang kamu lakukan?","What do you do?"],
    opts:[
     {t:["Terima kasih sudah percaya padaku. Ini perlu diketahui orang dewasa agar kamu aman. Ayo kita temui Bu Dewi sekarang, aku temani.","Thank you for trusting me. An adult needs to know so you stay safe. Let's see Bu Dewi now, I'll stay with you."],pts:20,
      fb:["Tepat! Saat keselamatan terancam, orang dewasa tepercaya harus dilibatkan, dan kamu tetap menemaninya.","Right! When safety is at risk, a trusted adult must be involved, and you stay by his side."]},
     {t:["Kamu hindari saja orang itu dan semoga berhenti sendiri.","Just avoid that person and hope it stops by itself."],pts:10,
      fb:["Menghindar membantu, tetapi tekanan seperti ini perlu dibantu orang dewasa.","Avoiding helps, but pressure like this needs an adult's help."]},
     {t:["Aku akan mendatangi orang itu dan menyuruhnya berhenti.","I'll go to that person and tell them to stop."],pts:0,
      fb:["Menghadapi sendiri bisa berbahaya. Biarkan orang dewasa yang menanganinya.","Confronting alone can be dangerous. Let adults handle it."]},
     {t:["Oke, aku janji tidak akan bilang siapa pun.","Okay, I promise not to tell anyone."],pts:0,
      fb:["Rahasia yang membahayakan keselamatan tidak boleh disimpan sendirian. Coba lagi!","A secret that risks safety should not be kept alone. Try again!"]}],
    hint:["Jika keselamatan seseorang terancam, orang dewasa tepercaya perlu tahu, dan kamu bisa menemaninya.","If someone's safety is at risk, a trusted adult needs to know, and you can go with them."],
    note:["Berjanji merahasiakan tidak berlaku jika keselamatan terancam. Temani temanmu menemui orang dewasa.","A promise of secrecy does not apply when safety is at risk. Go with your friend to an adult."]}
  ]},

/* ───────────────────────── MISSION 5 ───────────────────────── */
{ id:5, icon:"🌟", badge:"champion", cat:"empathy", mod:5, bg:"kampanye",
  title:["Misi Sekolah Bersinar","The School Campaign"],
  place:["Hari kegiatan sekolah","School festival day"],
  mech:[["Seret dan lepas","Drag and drop"],["Penyusun kampanye","Campaign builder"],["Mitos atau fakta","Myth or fact"],["Keputusan akhir","Final decision"]],
  intro:["Sekolahmu mengadakan Hari Sekolah Bersinar! Bersama timmu, buat kampanye yang positif, akurat, dan menghargai semua orang.","Your school is holding School Bersinar Day! With your team, build a campaign that is positive, accurate and respectful."],
  reward:["Juara THE BRAVE WAY","BRAVE WAY CHAMPION"],
  rewardDesc:["Kamu memimpin kampanye sekolah yang aman, positif, dan penuh empati.","You helped lead a school campaign that is safe, positive and full of empathy."],
  scenes:[
  { title:["Slogan untuk Poster","Slogans for the Poster"], bg:"perpus", cast:["nia"], type:"sort", cat:"empathy",
    lines:[["nia",["Kita sedang menyusun poster kampanye. Slogan mana yang boleh dipasang?","We're designing the campaign poster. Which slogans can go up?"]]],
    q:["Tarik slogan ke kolom yang tepat, atau ketuk slogan lalu kolomnya.","Drag each slogan to the right column, or tap a slogan then the column."],
    bins:[["Pasang!","Put it up!"],["Perlu diubah","Needs changing"]],
    items:[
     {t:["Berani Menolak, Berani Melapor!","Brave to Say No, Brave to Speak Up!"],bin:0},
     {t:["Teman sehat, masa depan hebat!","Healthy friends, a great future!"],bin:0},
     {t:["Bersama kita aman dan bersinar!","Together we stay safe and shine!"],bin:0},
     {t:["Mereka itu berbahaya, jauhi mereka!","They are dangerous, stay away from them!"],bin:1,why:["Melabeli orang membuat mereka takut mencari bantuan.","Labelling people makes them afraid to ask for help."]},
     {t:["Awas, siapa yang salah akan dipermalukan!","Watch out, anyone at fault will be shamed!"],bin:1,why:["Mempermalukan tidak membantu siapa pun.","Shaming helps nobody."]},
     {t:["Hanya anak nakal yang butuh kampanye ini.","Only bad kids need this campaign."],bin:1,why:["Pencegahan penting untuk semua siswa.","Prevention matters for every student."]}],
    hint:["Pilih slogan yang mengajak, menyemangati, dan tidak menyalahkan orang tertentu.","Choose slogans that invite, encourage and do not blame particular people."],
    note:["Pesan kampanye yang baik itu positif dan merangkul, bukan menakut-nakuti atau menyalahkan.","A good campaign message is positive and inclusive, not scary or blaming."]},

  { title:["Kegiatan Positif","Positive Activities"], bg:"kampanye", cast:["guru"], type:"select", cat:"safety", style:"chips",
    lines:[["guru",["Pilih kegiatan positif untuk Hari Sekolah Bersinar. Mana yang cocok?","Choose positive activities for School Bersinar Day. Which fit?"]]],
    q:["Pilih semua kegiatan yang cocok.","Choose all the activities that fit."],
    items:[
     {t:["Turnamen olahraga persahabatan","Friendly sports tournament"],ok:true},
     {t:["Lomba mural dan poster","Mural and poster contest"],ok:true},
     {t:["Talkshow radio sekolah bersama guru BK","School radio talk with the counselor"],ok:true},
     {t:["Klub baca dan komunitas hobi","Reading club and hobby communities"],ok:true},
     {t:["Menggeledah tas teman secara diam-diam","Secretly searching friends' bags"],ok:false,why:["Mengawasi dan menggeledah teman merusak kepercayaan.","Spying on and searching friends damages trust."]},
     {t:["Membuat daftar siswa yang dicurigai","Making a list of suspected students"],ok:false,why:["Menuduh tanpa dasar menyakiti dan tidak adil.","Accusing without proof hurts and is unfair."]}],
    hint:["Kegiatan yang baik membuat siswa aktif, sehat, dan saling mendukung.","Good activities keep students active, healthy and supportive."],
    note:["Kegiatan positif seperti olahraga, seni, dan literasi membangun lingkungan sekolah yang aman.","Positive activities like sports, arts and literacy build a safe school."]},

  { title:["Tantangan Pengetahuan","Knowledge Challenge"], bg:"kampanye", cast:["petugas"], type:"mcq", cat:"safety",
    lines:[["petugas",["Sebelum kampanye dimulai, pastikan informasi yang kita bagikan akurat. Mitos atau fakta?","Before the campaign starts, make sure the information we share is accurate. Myth or fact?"]]],
    q:["Mitos atau fakta?","Myth or fact?"],
    items:[
     {q:["Berkata \"tidak\" adalah tanda kekuatan, bukan kelemahan.","Saying \"no\" is a sign of strength, not weakness."],opts:MF,ok:1,why:["Fakta. Berani menolak melindungi dirimu.","Fact. Being brave enough to refuse protects you."]},
     {q:["Hanya siswa yang \"nakal\" yang perlu belajar pencegahan narkoba.","Only \"naughty\" students need to learn about drug prevention."],opts:MF,ok:0,why:["Mitos. Pencegahan penting untuk semua orang.","Myth. Prevention matters for everyone."]},
     {q:["Kita tidak bisa memastikan sebuah zat aman hanya dengan melihatnya.","You cannot tell whether a substance is safe just by looking at it."],opts:MF,ok:1,why:["Fakta. Karena itu benda tak dikenal tidak boleh dicoba.","Fact. That is why unknown items must never be tried."]},
     {q:["Siswa sebaiknya menyelidiki sendiri orang yang mencurigakan.","Students should investigate suspicious people themselves."],opts:MF,ok:0,why:["Mitos. Laporkan kepada orang dewasa tepercaya.","Myth. Report to a trusted adult."]},
     {q:["Meminta bantuan orang dewasa tepercaya adalah tindakan yang berani.","Asking a trusted adult for help is a brave action."],opts:MF,ok:1,why:["Fakta. Orang dewasa tepercaya ada untuk membantumu.","Fact. Trusted adults are there to help you."]}],
    hint:["Ingat: menolak itu kuat, melapor itu berani, dan pencegahan untuk semua.","Remember: refusing is strong, reporting is brave, and prevention is for everyone."],
    note:["Informasi kampanye harus akurat dan tidak menstigma siapa pun.","Campaign information must be accurate and must not stigmatise anyone."]},

  { title:["Rapat Tim yang Memanas","The Tense Team Meeting"], bg:"kampanye", cast:["dito","nia"], type:"choice", cat:"empathy",
    lines:[["dito",["Aku mau pasang foto menyeramkan dan nama siswa yang \"bermasalah\" di poster!","I want to put a scary photo and the name of a \"troubled\" student on the poster!"]],
           ["nia",["Aku tidak setuju, tapi aku tidak tahu bagaimana mengatakannya…","I disagree, but I don't know how to say it…"]]],
    q:["Sebagai anggota tim, apa yang kamu lakukan?","As a team member, what do you do?"],
    opts:[
     {t:["Ajak berdiskusi: \"Kita fokus pada pesan positif dan jangan menyebut nama siapa pun. Yuk, voting ide.\"","Invite discussion: \"Let's focus on positive messages and not name anyone. Let's vote on ideas.\""],pts:20,
      fb:["Kamu menjaga kerja sama, menghormati semua suara, dan melindungi martabat orang lain.","You protected teamwork, respected every voice and protected other people's dignity."]},
     {t:["Mengerjakan bagianku sendiri dan tidak ikut campur.","Do my own part and stay out of it."],pts:10,
      fb:["Fokus pada tugas itu baik, tetapi tim butuh suaramu untuk menjaga pesan tetap positif.","Focusing on your task is fine, but the team needs your voice to keep the message positive."]},
     {t:["Setuju saja supaya cepat selesai.","Agree so it finishes quickly."],pts:0,
      fb:["Menyebut nama siswa bisa mempermalukannya. Kamu boleh menyampaikan pendapat dengan sopan.","Naming a student can embarrass them. You may share your opinion politely."]},
     {t:["Mengambil alih semua pekerjaan sendiri.","Take over all the work myself."],pts:0,
      fb:["Kampanye berhasil lewat kerja sama, bukan satu orang.","Campaigns succeed through teamwork, not one person."]}],
    hint:["Kerja sama yang baik: dengarkan, diskusi, dan pilih pesan yang tidak menyakiti siapa pun.","Good teamwork: listen, discuss and choose messages that hurt no one."],
    note:["Kerja sama berarti mendengarkan semua suara dan menjaga martabat setiap orang.","Teamwork means hearing every voice and protecting everyone's dignity."]},

  { title:["Keputusan Akhir","The Final Decision"], bg:"kampanye", cast:["nia"], type:"choice", cat:"voice",
    lines:[["nia",["Kak, aku khawatir dengan temanku. Dia berubah dan sering diam. Aku harus bagaimana?","Hi, I'm worried about my friend. They've changed and are often quiet. What should I do?"]]],
    q:["Apa sarannya?","What is your advice?"],
    opts:[
     {t:["Terima kasih sudah peduli. Jangan menebak atau menyelidiki sendiri. Dengarkan temanmu dengan baik, lalu ajak bicara dengan guru atau guru BK.","Thank you for caring. Don't guess or investigate on your own. Listen to your friend kindly, then invite them to talk to a teacher or counselor."],pts:20,
      fb:["Saran yang lengkap: peduli, tidak menghakimi, dan melibatkan orang dewasa.","A complete answer: caring, not judging, and involving adults."],
      next:{lines:[["nia",["Oke, aku akan coba. Pesan apa yang bisa kita bagikan kepada semua siswa?","Okay, I'll try. What message can we share with all students?"]]],
        q:["Kamu menutup kampanye dengan pesan…","You end the campaign with the message…"],
        opts:[
         {t:["Berani Menolak, Berani Melapor, Berani Peduli. Kita semua bisa menjadi teman yang aman.","Brave to say no, brave to speak up, brave to care. We can all be safe friends."],pts:20,
          fb:["Pesan yang positif, merangkul, dan mengajak bertindak!","A positive, inclusive message that invites action!"]},
         {t:["Pokoknya jangan coba-coba!","Just don't ever try it!"],pts:10,
          fb:["Pesan tegas, tetapi belum memberi tahu apa yang bisa dilakukan atau ke mana mencari bantuan.","A firm message, but it doesn't say what to do or where to find help."]},
         {t:["Siapa yang aneh harus dijauhi.","Anyone strange should be avoided."],pts:0,
          fb:["Pesan ini menstigma dan membuat orang takut meminta tolong.","This message stigmatises and makes people afraid to ask for help."]},
         {t:["Tidak perlu pesan apa-apa.","No message is needed."],pts:0,
          fb:["Pesan positif membantu semua siswa tahu cara menjaga diri dan mencari bantuan.","A positive message helps all students know how to stay safe and find help."]}]}},
     {t:["Ajak temanmu bicara baik-baik saja, tanpa memberi tahu siapa pun.","Just talk kindly to your friend, without telling anyone."],pts:10,
      fb:["Berbicara baik-baik itu bagus, tetapi orang dewasa tepercaya juga bisa membantu.","Talking kindly is good, but a trusted adult can help too."]},
     {t:["Cari tahu sendiri diam-diam apa yang dilakukan temanmu.","Secretly find out on your own what your friend is doing."],pts:0,
      fb:["Menyelidiki sendiri bisa merusak kepercayaan dan berbahaya. Minta bantuan orang dewasa.","Investigating alone can damage trust and be dangerous. Ask an adult for help."]},
     {t:["Bilang saja itu bukan urusanmu.","Just say it's not your business."],pts:0,
      fb:["Kepedulian Nia perlu didukung. Kamu bisa menunjukkan cara membantu dengan aman.","Nia's concern deserves support. You can show how to help safely."]}],
    hint:["Peduli, jangan menebak atau menyelidiki, dan libatkan orang dewasa tepercaya.","Care, don't guess or investigate, and involve a trusted adult."],
    note:["Menjadi juara THE BRAVE WAY berarti berani menolak, berani melapor, dan berani peduli.","Being a BRAVE WAY champion means being brave to refuse, to speak up and to care."]}
  ]}
];

